 {'slot':'straight-pants','id':'female-reference-taupe-straight-pants-v1','label':'灰褐直筒裤候选','source_manifest':'prototype/public/assets/m1/equipment.json','source_id':'m1-training-pants','source_path':'prototype/public/assets/m1/m1-training-pants.glb','color':'#8A7A70','status':'fallback-candidate','shape':'source knee-length training pants, exact base-female fit','limits':['Reference requires ankle-length straight trousers. Existing source ends at the knee and is retained only as a fallback candidate.','No new long-pants geometry was authored.']},
