 fit={'schema':'female-reference-outfit-fit-v1','id':item['id']+'-fit','slot':item['slot'],'body':body_lock,'sourceAsset':{'id':item['source_id'],'path':item['source_path'],'sha256':sha(src),'bytes':src.stat().st_size},'sourceFitId':entry.get('fitId'),'method':entry.get('method'),'staticSourceFit':True,'runtimeAccepted':False,'limits':item['limits']}
 cov={'schema':'female-reference-outfit-coverage-v1','id':item['id']+'-coverage','slot':item['slot'],'bodySha256':body_sha,'sourceAssetSha256':sha(src),'preserveOriginalBody':entry.get('preserveOriginalBody',False),'sourceCoverage':'existing equipment entry preserveOriginalBody and source fit only','status':'candidate','runtimeAccepted':False,'limits':item['limits']}
 manifest={'schema':'zbgs-equipment-candidate-v1','id':item['id'],'slot':item['slot'],'name':item['label'],'status':item['status'],'sourceEntry':entry,'sourcePath':item['source_path'],'sourceSha256':sha(src),'sourceBytes':src.stat().st_size,'bodySha256':body_sha,'materialRecipe':'recipe.json','fit':'fit.json','coverage':'coverage.json','sourceLock':'source-lock.json','license':entry['sourceLicense'],'limits':item['limits']}
 for name,obj in [('recipe.json',recipe),('fit.json',fit),('coverage.json',cov),('manifest.json',manifest),('source-lock.json',lock)]: write(d/name,obj)
