 matrix['styles'].append({'styleId':item['id'],'label':item['label'],'variants':[{'bodyType':'female','bodySha256':body_sha,'recipeSource':rp,'recipeSha256':sha(ROOT/rp),'resourceManifest':url+'#'+sid,'resourceManifestSha256':msha,'fitManifest':url+'#'+sid+'.bindings','fitManifestSha256':msha,'coverageManifest':url+'#'+sid+'.preserveOriginalBody','coverageManifestSha256':msha,'status':'candidate','variantVersion':'v1','budgetStatus':'pending-source-check','admissionBlockers':item['limits'],'limits':item['limits']}]})
