for item in items:
 d=PKG/item['slot']; closure['slots'].append({'slot':item['slot'],'id':item['id'],'source':next(x for x in rows if x['id']==item['id'])['source'],'files':[{'path':rel(d/f),'sha256':sha(d/f),'bytes':(d/f).stat().st_size} for f in ['recipe.json','manifest.json','fit.json','coverage.json','source-lock.json']]})
